<script setup>import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,Link,router}from'@inertiajs/vue3';const p=defineProps({quotation:Object});</script><template><Head :title="quotation.quotation_number"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="quotations"/></template><div v-if="$page.props.flash.success" class="success-message mb-4">{{ $page.props.flash.success }}</div><div class="mb-5 flex flex-wrap justify-between gap-3"><div><h1 class="text-3xl font-bold">{{ quotation.quotation_number }}</h1><p class="uppercase text-slate-500">{{ quotation.status }}</p></div><div class="flex gap-2"><button onclick="window.print()" class="rounded-xl border px-5 py-3 font-bold">Print / PDF</button><Link v-if="quotation.status==='draft'" :href="route('admin.quotations.edit',quotation.uuid)" class="rounded-xl border px-5 py-3 font-bold">Edit</Link><button v-if="quotation.status==='draft'" class="form-button" @click="router.post(route('admin.quotations.send',quotation.uuid))">Send</button><button v-if="quotation.status==='accepted'" class="form-button" @click="router.post(route('admin.quotations.convert',quotation.uuid))">Convert to invoice</button></div></div><div class="rounded-2xl bg-white p-8 shadow print:shadow-none"><div class="flex justify-between"><div><h2 class="text-2xl font-bold text-[#0B3D6E]">KernelBridge Technologies LTD</h2><p>Professional software solutions</p></div><div class="text-right"><strong>QUOTATION</strong><p>{{ quotation.issue_date }} — {{ quotation.expiry_date }}</p></div></div><div class="my-8"><p class="text-xs uppercase text-slate-500">Prepared for</p><h3 class="text-xl font-bold">{{ quotation.customer.name }}</h3><p>{{ quotation.customer.billing_address }}</p></div><table class="w-full"><thead><tr class="border-b"><th class="py-3 text-left">Description</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><tr v-for="i in quotation.items" :key="i.uuid" class="border-b"><td class="py-4">{{ i.product }} {{ i.plan }}<br/><small>{{ i.description }}</small></td><td class="text-center">{{ i.quantity }}</td><td class="text-right">{{ quotation.currency }} {{ i.unit_price }}</td><td class="text-right">{{ quotation.currency }} {{ i.total }}</td></tr></tbody></table><dl class="ml-auto mt-6 w-72 space-y-2"><div class="flex justify-between"><dt>Subtotal</dt><dd>{{ quotation.subtotal }}</dd></div><div class="flex justify-between"><dt>Discount</dt><dd>{{ quotation.discount }}</dd></div><div class="flex justify-between"><dt>Tax</dt><dd>{{ quotation.tax }}</dd></div><div class="flex justify-between border-t pt-2 text-xl font-bold"><dt>Total</dt><dd>{{ quotation.currency }} {{ quotation.total }}</dd></div></dl><div class="mt-10 grid gap-6 md:grid-cols-2"><div><h4 class="font-bold">Notes</h4><p class="whitespace-pre-line text-sm">{{ quotation.notes }}</p></div><div><h4 class="font-bold">Terms</h4><p class="whitespace-pre-line text-sm">{{ quotation.terms }}</p></div></div></div></PortalLayout></template>
